<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api } from '../api/client'
import type { GlobalRole, PageResponse, User } from '../api/types'
const users=ref<User[]>([]); const dialog=ref(false); const form=reactive<{username:string;name:string;email:string;globalRole:GlobalRole;password:string}>({username:'',name:'',email:'',globalRole:'USER',password:''})
async function load(){try{users.value=(await api<PageResponse<User>>('GET','/users',undefined,{size:100})).list}catch(e){ElMessage.error((e as Error).message)}}
async function create(){try{await api('POST','/users',form);dialog.value=false;Object.assign(form,{username:'',name:'',email:'',globalRole:'USER',password:''});await load()}catch(e){ElMessage.error((e as Error).message)}}
async function toggle(user:User){try{await api('PUT',`/users/${user.id}`,{name:user.name,email:user.email,globalRole:user.globalRole,active:!user.active});await load()}catch(e){ElMessage.error((e as Error).message)}}
async function reset(user:User){try{const value=await ElMessageBox.prompt(`为 ${user.name} 设置新密码`,'重置密码',{inputType:'password',inputPattern:/.{8,72}/,inputErrorMessage:'密码需为 8-72 位'});await api('PUT',`/users/${user.id}/password`,{password:value.value});ElMessage.success('密码已重置')}catch(e){if(e!=='cancel')ElMessage.error((e as Error).message)}} onMounted(load)
</script>
<template><div><header class="page-head"><div><h1>账号管理</h1><p>创建账号、调整全局角色、停用与重置密码。</p></div><el-button type="primary" @click="dialog=true">创建账号</el-button></header><section class="surface"><el-table :data="users"><el-table-column prop="username" label="用户名"/><el-table-column prop="name" label="姓名"/><el-table-column prop="email" label="邮箱"/><el-table-column prop="globalRole" label="角色"/><el-table-column label="状态"><template #default="scope"><el-tag :type="scope.row.active?'success':'info'">{{scope.row.active?'有效':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="scope"><el-button link @click="reset(scope.row)">重置密码</el-button><el-button link :type="scope.row.active?'danger':'success'" @click="toggle(scope.row)">{{scope.row.active?'停用':'启用'}}</el-button></template></el-table-column></el-table></section><el-dialog v-model="dialog" title="创建账号"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email"/></el-form-item><el-form-item label="角色"><el-select v-model="form.globalRole" style="width:100%"><el-option label="管理员" value="ADMIN"/><el-option label="普通用户" value="USER"/><el-option label="只读观察者" value="VIEWER"/></el-select></el-form-item><el-form-item label="初始密码"><el-input v-model="form.password" type="password" show-password/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog></div></template>
